BEGIN;

-- Step 1: Deduct funds from sender
UPDATE accounts SET balance = balance - 250 WHERE id = 101;

-- Step 2: Add funds to receiver
UPDATE accounts SET balance = balance + 250 WHERE id = 102;

-- Set intermediate rollback point
SAVEPOINT before_optional_bonus;

-- Step 3: Optional promotion insertion
INSERT INTO bonuses (account_id, amount) VALUES (102, 25);

-- Roll back only bonus if needed
ROLLBACK TO SAVEPOINT before_optional_bonus;

COMMIT;
